(63, 'Muhammad Shahzad  Muhammad Nawaz', '../../uploads/17530906431373.jpg', 'Shahzad', 'f7fbc4bafcc80cbf690acbef25f2ce1c', 'Tyre Technician', '0588362723', 'rsa@cg.ae', 2200, 1000, 'Service Center', 'Service Center Operations Department', 'Tyre Technicians', '2022-10-02', '2026-10-25', '[\"https://cg2uploads.s3.amazonaws.com/1753091207170.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753091207171.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753091207172.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753091207171.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753091207172.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753091207173.jpg\"]', '', '', '', '', '', '', '', 'NU5157632', 'With Company', '2033-06-04', '0000-00-00', '2026-09-30', '2025-09-02', 'Pakistan', 'OKSONS', '1985-01-01', '784-1985-2764748-5', '2026-10-24 20:00:00', 'Supervisor', 0, '', 'Employed', '', 1, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-15 13:07:32', 0, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"Tyre Mechanics\r\n \r\n 1. Tire Inspection: Conduct thorough inspections of tires to assess their condition, tread depth, inflation pressure, and overall integrity.\r\n 2. Tire Repair: Perform tire repairs such as patching punctures, repairing cuts, and fixing leaks.\r\n 3. Tire Installation and Balancing: Mount and dismount tires onto rims or wheels using specialized equipment such as tire changers and balancers. \r\n 4. Tire Replacement: Replace tires when they are worn beyond safe limits or damaged beyond repair. \r\n 5. Tire Maintenance: Provide routine tire maintenance services such as tire pressure checks, tire inflation, and tire cleaning.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Tire Inspection: Conduct thorough inspections of tires to assess their condition, tread depth, inflation pressure, and overall integrity.<br>2. Tire Repair: Perform tire repairs such as patching punctures, repairing cuts, and fixing leaks.<br>3. Tire Installation and Balancing: Mount and dismount tires onto rims or wheels using specialized equipment such as tire changers and balancers.<br>4. Tire Replacement: Replace tires when they are worn beyond safe limits or damaged beyond repair.<br>5. Tire Maintenance: Provide routine tire maintenance services such as tire pressure checks, tire inflation, and tire cleaning.</span><br></p>', NULL, '2025-11-08 05:00:00', '2025-11-08 17:00:00', 'Sunday', 0, 0, 1, 52042, 2, 400, 0, NULL, 'Yes'),
