(77, 'Abid Ali Ahmed Ali', '../../uploads/17530899855419.jpg', 'Abid Ali', 'c6d2348f780148793d82d91cb4ee50d6', 'Head Inspector', '0509382165', 'rsa@cg.ae', 5500, 2500, 'Service Center', 'Service Center Operations Department', 'Inspector', '2022-08-29', '2026-10-13', '[\"https://cg2uploads.s3.amazonaws.com/1753090560249.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753090560249.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753090560248.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753090560250.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753090560250.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753090560249.jpeg\"]', '', '', '', '', '', '', '', 'PF1802122', 'With Them', '2033-03-13', '0000-00-00', '2026-08-27', '2025-09-02', 'Pakistan', '800CARGURU', '1975-01-01', '784-1975-5902526-3', '2026-10-12 20:00:00', 'Supervisor', 0, '', 'Terminated', '', 0, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-15 13:51:09', 509382165, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"Mechanics\r\n \r\n 1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.\r\n 2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately. \r\n 3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results. \r\n 4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems. \r\n 5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency. \r\n 6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.<br>2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately.<br>3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results.<br>4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems.<br>5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency.<br>6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.</span><br></p>', '', '2025-11-24 05:00:00', '2025-11-24 15:00:00', 'Sunday', 34, 0, 3, 52042, 2, 400, 0, '2025-11-18 20:00:00', 'No'),
(78, 'Muhammad Sarfraz Muhammad Ismail', '../../uploads/17530897617759.jpg', 'Sarfraz', 'c1fc691de8e9dfb5c0070b0a9e419a0a', 'Electrician', 'Not Available', 'rsa@cg.ae', 2200, 1000, 'Service Center', 'Service Center Operations Department', 'Electrician', '2022-11-01', '2027-08-14', '[\"https://cg2uploads.s3.amazonaws.com/1753090358414.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753090358413.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753090358414.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753090358415.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753090358412.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753090358415.jpg\"]', '', '', '', '', '', '', '', 'BC5982133', 'With Company', '2034-12-24', '0000-00-00', '0001-01-01', '2025-09-02', 'Pakistan', '800CARGURU Freezone', '1988-06-12', '784-1988-6570732-1', '2027-08-13 20:00:00', 'Supervisor', 0, '', 'Terminated', '', 0, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-15 13:55:21', 525293299, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles. \r\n 2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors.\r\n 3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets.\r\n 4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses.\r\n 5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality. \r\n 6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles.<br>2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors.<br>3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets.<br>4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses.<br>5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality.<br>6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.</span><br></p>', 'dPGV7JYH2j1Ez96uSKgQip:APA91bEvR0huXMJVZsLHhhiJokRZxzfMGjJraSKkk0O90kylEUn6G0ZurIPDQiV6_EsHOyIvywVoVqNF0wyQwBZ2ImybUc9Q3Sb_O922FVZLdjmfg15GfoUBW7cVYIti6uQhecfYFn7U', '2025-10-07 05:00:00', '2025-10-07 17:00:00', 'Sunday', 34, 0, 2, 52042, 2, 400, 0, '2025-10-06 20:00:00', 'Yes'),
