(92, 'Muhammad Saad Sami Ullah', '../../uploads/17530880855130.png', 'Saad_1', 'c8b5bbd5ac5696b34188ebd82a6d730b', 'Tyre Technician', 'Not Available', 'rsa@cg.ae', 4000, 1500, 'Service Center', 'Service Center Operations Department', 'Tyre Technicians', '2021-11-24', '2028-02-06', '[\"https://cg2uploads.s3.amazonaws.com/1753088675355.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753088675356.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753088675356.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753088675354.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753088675355.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753088675356.pdf\"]', '', '', '', '', '', '', '', 'DT5494122', 'With Company', '2033-10-21', '0000-00-00', '0001-01-01', '2025-09-02', 'Pakistan', '800CARGURU Freezone', '2000-03-01', '784-2000-1439297-9', '2028-02-05 20:00:00', 'Supervisor', 0, '', 'Employed', '', 1, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-15 14:43:38', 551880314, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"Tyre Mechanics\r\n \r\n 1. Tire Inspection: Conduct thorough inspections of tires to assess their condition, tread depth, inflation pressure, and overall integrity.\r\n 2. Tire Repair: Perform tire repairs such as patching punctures, repairing cuts, and fixing leaks.\r\n 3. Tire Installation and Balancing: Mount and dismount tires onto rims or wheels using specialized equipment such as tire changers and balancers. \r\n 4. Tire Rotation: Rotate tires on vehicles according to manufacturer recommendations to promote even tread wear and extend tire lifespan. \r\n 5. Wheel Alignment: Perform wheel alignment procedures to adjust the angles of vehicle wheels according to manufacturer specifications. \r\n 6. Tire Replacement: Replace tires when they are worn beyond safe limits or damaged beyond repair. \r\n 7. Tire Maintenance: Provide routine tire maintenance services such as tire pressure checks, tire inflation, and tire cleaning.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Tire Inspection: Conduct thorough inspections of tires to assess their condition, tread depth, inflation pressure, and overall integrity.<br>2. Tire Repair: Perform tire repairs such as patching punctures, repairing cuts, and fixing leaks.<br>3. Tire Installation and Balancing: Mount and dismount tires onto rims or wheels using specialized equipment such as tire changers and balancers.<br>4. Tire Rotation: Rotate tires on vehicles according to manufacturer recommendations to promote even tread wear and extend tire lifespan.<br>5. Wheel Alignment: Perform wheel alignment procedures to adjust the angles of vehicle wheels according to manufacturer specifications.<br>6. Tire Replacement: Replace tires when they are worn beyond safe limits or damaged beyond repair.<br>7. Tire Maintenance: Provide routine tire maintenance services such as tire pressure checks, tire inflation, and tire cleaning.</span><br></p>', NULL, '2026-02-09 06:00:00', '2026-02-09 16:00:00', 'Sunday', 0, 0, 2, 52042, 2, 400, 0, NULL, 'Yes'),
