(112, 'Saif Ullah ', NULL, 'Saif Ullah', 'c95f5116a1dda5f6afe902f1d8b116ea', 'Electrician', '0561805736', 'rsa@cg.ae', 2000, NULL, NULL, 'Service Center 1', 'Workshop', '2023-01-01', '0001-01-01', NULL, '', '', '', '', '', '', '', '0000', 'With Them', '0001-01-01', '0001-01-01', '0001-01-01', '0001-01-01', 'Pakistan', 'OUTSIDE', '0001-01-01', '000', NULL, 'Supervisor', 0, '', 'Employed', '', 0, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-15 15:13:04', 0, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles. \\n 2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors.\\n 3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets.\\n 4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses.\\n 5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality. \\n 6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles.<br>2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors.<br>3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets.<br>4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses.<br>5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality.<br>6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.</span><br></p>', NULL, NULL, NULL, 'Sunday', NULL, 0, 0, NULL, NULL, NULL, 0, NULL, NULL),
(113, 'Sameer Khan Bashir Khan', '../../uploads/17531020214264.JPG', 'Sameer Khan', 'fe42df4148977c58790dd059726c9787', 'Tyre Technician', 'Not Available', 'rsa@cg.ae', 2800, 1000, 'Service Center', 'Service Center Operations Department', 'Tyre Technicians', '2023-03-04', '2027-08-28', '[\"https://cg2uploads.s3.amazonaws.com/1753102639983.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753102639984.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753102639984.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753102639985.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753102639985.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753102639985.jpeg\"]', '', '', '', '', '', '', '', 'R3840476', 'With Them', '2027-09-18', '0000-00-00', '0001-01-01', '2025-09-02', 'Indian', '800CARGURU Freezone', '1992-09-26', '784-1992-5941438-3', '2027-08-27 20:00:00', 'Supervisor', 0, '', 'Terminated', '', 0, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-15 15:14:09', 551247865, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"Tyre Mechanics\r\n \r\n 1. Tire Inspection: Conduct thorough inspections of tires to assess their condition, tread depth, inflation pressure, and overall integrity.\r\n 2. Tire Repair: Perform tire repairs such as patching punctures, repairing cuts, and fixing leaks.\r\n 3. Tire Installation and Balancing: Mount and dismount tires onto rims or wheels using specialized equipment such as tire changers and balancers. \r\n 4. Tire Rotation: Rotate tires on vehicles according to manufacturer recommendations to promote even tread wear and extend tire lifespan. \r\n 5. Wheel Alignment: Perform wheel alignment procedures to adjust the angles of vehicle wheels according to manufacturer specifications. \r\n 6. Tire Replacement: Replace tires when they are worn beyond safe limits or damaged beyond repair. \r\n 7. Tire Maintenance: Provide routine tire maintenance services such as tire pressure checks, tire inflation, and tire cleaning.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Tire Inspection: Conduct thorough inspections of tires to assess their condition, tread depth, inflation pressure, and overall integrity.<br>2. Tire Repair: Perform tire repairs such as patching punctures, repairing cuts, and fixing leaks.<br>3. Tire Installation and Balancing: Mount and dismount tires onto rims or wheels using specialized equipment such as tire changers and balancers.<br>4. Tire Rotation: Rotate tires on vehicles according to manufacturer recommendations to promote even tread wear and extend tire lifespan.<br>5. Wheel Alignment: Perform wheel alignment procedures to adjust the angles of vehicle wheels according to manufacturer specifications.<br>6. Tire Replacement: Replace tires when they are worn beyond safe limits or damaged beyond repair.<br>7. Tire Maintenance: Provide routine tire maintenance services such as tire pressure checks, tire inflation, and tire cleaning.</span><br></p>', NULL, '2025-10-15 05:00:00', '2025-10-15 17:00:00', 'Sunday', 0, 0, 2, 52043, 2, 400, 0, '2025-10-06 20:00:00', 'Yes'),
(114, 'Fahid Shabbir Muhammad Shabbir Zahid', NULL, 'Fahid', '5d4bbaf58bbea675560c6699d0b7d6d2', 'Mechanics', '0561826568', 'rsa@cg.ae', 3500, NULL, NULL, 'Service Center 1', 'Workshop', '2023-03-28', '2025-04-17', NULL, '', '', '', '', '', '', '', 'CC5139232', 'With Company', '2024-07-01', '0001-01-01', '2025-03-28', '2023-08-24', 'Pakistan', '800CARGURU BRANCH', '1992-03-19', '784-1992-2494396-1', NULL, 'Supervisor', 0, '', 'Employed', '', 0, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-15 15:15:10', 0, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"Mechanics\\n \\n 1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.\\n 2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately. \\n 3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results. \\n 4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems. \\n 5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency. \\n 6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.<br>2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately.<br>3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results.<br>4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems.<br>5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency.<br>6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.</span><br></p>', NULL, NULL, NULL, 'Sunday', NULL, 0, 0, NULL, NULL, NULL, 0, NULL, NULL),
