(132, 'Muhammad Rizwan Safdar Muhammad', '../../uploads/17531009497004.png', 'Muhammad Rizwan', 'f2929d47212e929af28c39e91c1f0110', 'Electrician', 'Not Available', 'rsa@cg.ae', 2000, 1000, 'Service Center', 'Service Center Operations Department', 'Electrician', '2023-08-01', '2025-11-21', '[\"https://cg2uploads.s3.amazonaws.com/1753101506175.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101506176.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101506173.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101506172.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101506174.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101506177.png\",\"https://cg2uploads.s3.amazonaws.com/1753101506180.png\"]', '', '', '', '', '', '', '', 'UH9890651', 'With Them', '2025-10-22', '0000-00-00', '2025-09-24', '2025-09-02', 'Pakistan', '800CARGURU BRANCH', '1999-10-01', '784199966958128', '2025-11-20 20:00:00', 'Supervisor', 0, '', 'Terminated', '', 0, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-22 07:25:12', 524826158, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles. \r\n 2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors.\r\n 3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets.\r\n 4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses.\r\n 5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality. \r\n 6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles.<br>2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors.<br>3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets.<br>4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses.<br>5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality.<br>6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.</span><br></p>', NULL, '2025-10-15 05:00:00', '2025-10-15 17:00:00', 'Sunday', 34, 0, 2, 52043, 2, 400, 0, '2025-10-10 20:00:00', 'Yes'),
(133, 'Mir Alam Alam Khan', '../../uploads/17531007035099.jpg', 'Mir Alam', '7b60271696c9f1cccf1a5ed223b60aab', 'Technician', 'Not Available', 'rsa@cg.ae', 2000, 1000, 'Service Center', 'Service Center Operations Department', 'Mechanic', '2023-05-05', '2027-09-22', '[\"https://cg2uploads.s3.amazonaws.com/1753101263064.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101263065.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101263066.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101263067.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753101263068.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101263069.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101263069.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101263070.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753101263071.jpg\"]', '', '', '', '', '', '', '', 'BZ1750713', 'With Them', '2028-02-09', '0000-00-00', '0001-01-01', '2025-09-02', 'Pakistan', '800CARGURU Freezone', '1990-01-01', '784199044806539', '2027-09-21 20:00:00', 'Supervisor', 0, '', 'Employed', '', 1, 0, '800carguru.dyndns.org:5188', '0', 'XML', 0, '', '', 0, '', '2023-05-23 11:52:33', 0, 'N/A', 'Dubai, UAE', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{\"1\":2,\"2\":\"Mechanics\r\n \r\n 1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.\r\n 2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately. \r\n 3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results. \r\n 4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems. \r\n 5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency. \r\n 6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.\"}\" data-sheets-userformat=\"{\"2\":14953,\"3\":{\"1\":0},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"12\":0,\"14\":{\"1\":2,\"2\":2172201},\"15\":\"Calibri, sans-serif\",\"16\":11}\" style=\"font-size: 11pt; font-family: Calibri, Arial;\">1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.<br>2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately.<br>3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results.<br>4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems.<br>5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency.<br>6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.</span><br></p>', NULL, '2026-03-24 05:00:00', '2026-03-24 17:00:00', 'Sunday', 0, 0, 1, 52043, 2, 400, 0, NULL, 'Yes'),
