(268, 'Syed Shah Muhammad Adeel ', '../../uploads/17530963761375.jpg', 'Adeel', 'e10adc3949ba59abbe56e057f20f883e', 'Head – Quotations & Workshop Control', '586037627', 'rsa@800carguru.ae', 2500, 1000, 'Service Center', 'Third Party Garage Operations Department', 'Service Coordinator', '2024-03-11', '2026-06-09', '[\"https://cg2uploads.s3.amazonaws.com/1753096727985.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753096727986.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753096727988.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753096727989.png\",\"https://cg2uploads.s3.amazonaws.com/1753096727987.pdf\"]', '', '', '', '', '', '', '', 'ZQ6907501', 'With Them', '2027-08-09', '0000-00-00', '2026-04-30', '2025-09-02', 'Pakistan', '800CARGURU BRANCH', '1986-10-17', '784198640314278', '2026-06-08 20:00:00', 'Supervisor', 50, '', 'Employed', '', 1, 0, '800carguru.dyndns.org:5188', '', 'XML', 0, '', '', 0, '', '2024-05-09 14:52:55', 0, '', 'Dubai, UAE', '<p class=\"MsoNormal\"><br></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Head – Quotations &amp; Workshop Control</span></b></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">\r\nRole Purpose<o:p></o:p></span></b></p><p class=\"MsoNormal\"><span lang=\"en-AE\">Maintain<b> quotation discipline, and assignments\r\nof workshops</b>.</span></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">\r\nAbsolute Ownership<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Quotation and pricing governance<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Assigning of Workshops</span></li></ul><p class=\"MsoNormal\"><b><span lang=\"en-AE\">\r\nKey Responsibilities<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Verify End-of-Day Statements<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Reject incomplete quotations<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Escalate inflated quotations<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Approve quotations strictly as per SLA<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Coordinate and manage complaints related to quotations<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Support <b>Head - Job Card Execution</b> to ensure on time\r\n     completion of Job cards.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Any other work assigned by immediate supervisor</span></li></ul><p class=\"MsoNormal\"><b><span lang=\"en-AE\">\r\nPerformance KPIs<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Quotation approval as per SLA - <b>100%</b><o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Accurately assignments of workshops<b> - 100%</b><o:p></o:p></span></li>\r\n</ul><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\"><span lang=\"en-AE\">&nbsp;</span></p>', 'cvSLUnEkhSx0lwkUtgQTax:APA91bFp8tjYi2qaWkj2itK3aM0xIOTPXC7D--mHbJdtecclHItwZhRRrJ9UsZslryEwu_MRfiEK6oYo6QISJ3EEBnvPVbTbXs_T1zYFBeyy4TwLudvLNt8', '2026-01-21 05:00:00', '2026-01-21 17:00:00', 'Sunday', 27, 1, 1, 520416, 2, 400, 0, NULL, 'Yes'),
