(321, 'Karim Abidi', '../../uploads/1753095567565.jpeg', 'Karim', '2b61596cdd6bffd02d0017ab68114017', 'Electrician', 'Not Available', 'info@800carguru.ae', 2500, 1000, 'Service Center', 'SC-02 Floor Operations Department', 'Electrician', '2024-09-02', '2026-11-18', '[\"https://cg2uploads.s3.amazonaws.com/1753096175842.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753096175844.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753096175846.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753096175843.jpg\",\"https://cg2uploads.s3.amazonaws.com/1753096175845.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753096175843.pdf\"]', '', '', '', '', '', '', '', '302545765', 'With Company', '2033-06-12', '0000-00-00', '2026-10-22', '2025-09-02', 'Algerian', '800CARGURU BRANCH', '1995-04-22', '784199510719471', '2026-11-17 20:00:00', 'Supervisor', 0, '', 'Terminated', '', 0, 1, '800carguru.dyndns.org:5188', '', 'XML', 1, '', '', 0, '', '2024-10-10 09:08:45', 0, '', '14C Street Al Quoz Industrial Area 04 Al Quoz Dubai UAE', '<p><span style=\"color: rgb(31, 31, 31);\">1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles. 2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors. 3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets. 4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses. 5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality. 6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.</span><br></p>', NULL, '2025-09-27 05:00:00', '2025-09-27 17:00:00', 'Sunday', 34, 0, 1, 52043, 2, 400, 0, '2025-08-25 20:00:00', 'Yes'),
(322, 'Blaise Nkam Ndoh', NULL, 'Blaise', '862e86dd5841ebcfa1ef56acadb33bf0', 'Inspector', 'Not Available', 'info@800carguru.ae', 3500, 0, 'Service Center', 'SC-02 Floor Operations Department', 'Inspector', '2024-09-26', '0001-01-01', NULL, '', '', '', '', '', '', '', 'AA167578', 'With Company', '2027-03-15', '0001-01-01', '0001-01-01', '0001-01-01', 'Cameroon', 'OUTSIDE', '1993-12-26', '0000', '0000-00-00 00:00:00', 'Supervisor', 0, '', 'Employed', '', 0, 1, '800carguru.dyndns.org:5188', '0', 'XML', 1, '', '', 0, '', '2024-10-10 09:12:54', 0, '', '14C Street Al Quoz Industrial Area 04 Al Quoz Dubai UAE', '<p>1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.</p><p>2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately. </p><p>3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results. </p><p>4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems. </p><p>5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency. </p><p>6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.</p>', 'dPGV7JYH2j1Ez96uSKgQip:APA91bEvR0huXMJVZsLHhhiJokRZxzfMGjJraSKkk0O90kylEUn6G0ZurIPDQiV6_EsHOyIvywVoVqNF0wyQwBZ2ImybUc9Q3Sb_O922FVZLdjmfg15GfoUBW7cVYIti6uQhecfYFn7U', '2025-06-18 05:00:00', '2025-06-18 17:00:00', 'Sunday', 34, 0, 0, NULL, NULL, NULL, 0, NULL, NULL);
