(332, 'Blasius Penn Awa', NULL, 'Blasius', '902b5f49246b3f6cddc0c8c5611bc1d1', 'Mechanic', 'Not Available', 'info@800carguru.ae', 4000, NULL, NULL, 'Service Center 1', 'Workshop', '2024-11-21', '0001-01-01', NULL, '', '', '', '', '', '', '', '1288031', 'With Them', '0001-01-01', '0001-01-01', '0001-01-01', '0001-01-01', 'Cameroon', 'OUTSIDE', '1986-12-25', '784198657179689', NULL, 'Supervisor', 0, '', 'Employed', '', 0, 1, '800carguru.dyndns.org:5188', '0', 'XML', 1, '', '', 0, '', '2024-11-23 09:03:13', 505417567, '', '14C Street Al Quoz Industrial Area 04 Al Quoz Dubai UAE', '<p>1. Vehicle Inspection: Conduct thorough inspections of vehicles to identify any mechanical, electrical, or other issues.</p><p>2. Diagnosis: Use diagnostic tools and equipment to identify problems accurately.&nbsp;</p><p>3. Repair and Maintenance: Perform repairs and maintenance tasks based on inspection findings and diagnostic results.&nbsp;</p><p>4. Mechanical Systems Repair: Repair and replace mechanical components such as engines, transmissions, brakes, steering systems, and suspension systems.&nbsp;</p><p>5. Performance Tuning: Perform performance tuning and upgrades to improve vehicle performance and efficiency.&nbsp;</p><p>6. Safety and Compliance: Ensure that vehicles meet safety and emissions standards set by regulatory authorities.</p>', NULL, NULL, NULL, 'Sunday', NULL, 0, 0, NULL, NULL, NULL, 0, NULL, NULL),
