(379, 'Zubair Ahmed Ghulam Mustafa', '../../uploads/17529097344444.jpeg', 'Zubair', 'bc0e5d91b49d625576438814beae4ffc', 'Director Operations', '557973142', 'rsa@800carguru.ae', 6000, 3000, 'Service Center', 'Third Party Garage Operations Department', 'Supervisor', '2025-01-16', '2026-12-17', '[\"https://cg2uploads.s3.amazonaws.com/1752910373100.pdf\",\"https://cg2uploads.s3.amazonaws.com/1752910373101.pdf\",\"https://cg2uploads.s3.amazonaws.com/1752910373102.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1752910373102.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1752910373102.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1752910373101.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1752910373103.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1752910373103.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1752910373104.pdf\"]', '', '', '', '', '', '', '', 'LA1158684', 'With Them', '2032-02-16', '0000-00-00', '0001-01-01', '0001-01-01', 'Pakistan', 'OUTSIDE', '1986-02-04', '784-1986-0946254-8', '2026-12-16 20:00:00', 'CEO', 100, '', 'Re Joined', '', 1, 1, '800carguru.dyndns.org:5188', '', 'XML', 1, '', '', 0, '', '2025-01-17 12:12:28', 559225445, '', 'Dubai', '<p class=\"MsoNormal\"><b><span lang=\"en-AE\" style=\"font-size:14.0pt;line-height:\r\n115%\">Director – Operations</span></b></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Role Purpose<o:p></o:p></span></b></p><p class=\"MsoNormal\"><span lang=\"en-AE\">Own end-to-end operational governance of\r\n800CarGuru. Act as <b>final authority</b> for escalations, garage governance,\r\nand operational discipline across the organization.</span></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Absolute Ownership<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Operations governance<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Escalation management<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Complaint oversight<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Garage governance (approval, Audits, Training Programs,\r\n     Classification, suspension, exit)<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Performance oversight of operations leadership</span></li></ul><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Key Responsibilities<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Garage classifications (A, B, C, D) and update regularly.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Conduct Quality Audits across garages.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Ensure training programs are completed timely.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Act as final authority on garage onboarding, suspension, or\r\n     exit<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Resolve escalations with immediate action<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Oversee and close operational complaints<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Monitor performance of all operations heads<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Ensure compliance with audits, SOPs, and circulars<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Any other work assigned by immediate supervisor</span></li></ul><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Performance KPIs<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">ALL KPIs of Operations Team (Hunain, Sagar, Azaz, Adeel)<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Immediate escalation resolution with <b>≤1% tolerance rate</b><o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Audit pass rate <b>≥90%</b> (A & B category garages)<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Training Completion on time <b>>90%</b></span></li><li class=\"MsoNormal\"><span lang=\"en-AE\"><b><span style=\"font-weight: 400;\">Complaint closure within </span><span style=\"font-weight: bolder; font-size: 1rem; text-indent: 0.25in;\">24 hours</span><span style=\"font-size: 1rem; font-weight: 400; text-indent: 0.25in;\"> (≤2% tolerance rate)</span><br></b></span><br></li></ul><p class=\"MsoNormal\" style=\"margin-left:0in;text-indent:.25in;mso-list:l2 level1 lfo3\"><span lang=\"en-AE\">\r\n<!--[if !supportLineBreakNewLine]--><br>\r\n<!--[endif]--><b><o:p></o:p></b></span></p>', 'cvSLUnEkhSx0lwkUtgQTax:APA91bFp8tjYi2qaWkj2itK3aM0xIOTPXC7D--mHbJdtecclHItwZhRRrJ9UsZslryEwu_MRfiEK6oYo6QISJ3EEBnvPVbTbXs_T1zYFBeyy4TwLudvLNt8', '2026-03-02 06:00:00', '2026-03-02 15:00:00', 'Sunday', 27, 1, 3, 520416, 2, 700, 0, NULL, 'No'),
