(430, 'Junaid Ahmad Ali Ikram', '../../uploads/17528295497212.jpeg', 'Junaid', '004fd779a0bacf1949e19a61372260df', 'Electrician', 'Not Available', 'Junaidkamboh73@gmail.com', 3000, 1500, 'Service Center', 'Service Center Operations Department', 'Electrician', '2025-07-12', '2025-06-28', '[\"https://cg2uploads.s3.amazonaws.com/1753271195155.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753271195152.pdf\",\"https://cg2uploads.s3.amazonaws.com/1753271195156.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753271195153.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1753271195154.jpeg\"]', '', '', '', '', '', '', '', 'GA1163593', 'With Company', '2027-03-09', '0000-00-00', '0001-01-01', '0001-01-01', 'Pakistan', 'CANCELLED VISA', '1980-09-22', '784-1980-472096-1', '2025-06-27 20:00:00', 'Supervisor', 0, '', 'Employed', '', 1, 0, '', '', '', 0, '', '', 0, '', '2025-07-18 09:05:48', 561171828, '', 'Dubai, UAE', '<p><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">1. Diagnosis and Troubleshooting: Use diagnostic tools and equipment to identify electrical issues in vehicles.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">2. Electrical Repairs: Repair or replace faulty electrical components such as alternators, starters, batteries, ignition systems, lights, switches, relays, wiring harnesses, and connectors.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">3. Installation of Electrical Accessories: Install aftermarket electrical accessories such as car stereos, amplifiers, speakers, GPS systems, alarms, remote starters, lighting upgrades, and auxiliary power outlets.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">4. Vehicle Rewiring: Perform partial or complete vehicle rewiring to replace outdated or damaged wiring harnesses.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">5. Electrical System Upgrades: Upgrade electrical systems to improve performance, reliability, and functionality.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">6. Electrical System Maintenance: Perform routine maintenance tasks to ensure the proper functioning of electrical systems.</span></p>', NULL, '2025-10-04 05:00:00', '2025-10-04 15:00:00', 'Sunday', 16, 0, 1, 52042, 2, 400, 0, NULL, 'Yes'),
