(450, 'Azazul Haque Maqbool Hasan', '../../uploads/17562082901652.jpeg', 'Azazul', '77ab8ad788cab67a15907e2dd792cc1f', 'Head – Job Card Execution', '586008495', 'azazulpbh@gmail.com', 3000, 1000, 'Service Center', 'Third Party Garage Operations Department', 'Service Coordinator', '2025-08-24', '2027-12-29', '[\"https://cg2uploads.s3.amazonaws.com/1756470238443.pdf\",\"https://cg2uploads.s3.amazonaws.com/1756470238442.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1756470238444.pdf\",\"https://cg2uploads.s3.amazonaws.com/1756470238444.pdf\",\"https://cg2uploads.s3.amazonaws.com/1756470238444.jpeg\"]', '', '', '', '', '', '', '', 'C4502999', 'With Them', '2034-10-21', '0000-00-00', '0001-01-01', '0001-01-01', 'Indian', '800CARGURU Freezone', '1999-07-06', '0000', '2027-12-28 20:00:00', 'Supervisor', 100, '', 'Employed', '', 1, 0, '', '', '', 0, '', '', 0, '', '2025-08-26 11:38:09', 563481821, '', 'Dubai,UAE', '<p class=\"MsoNormal\"><br></p>\r\n\r\n<p class=\"MsoNormal\"><b><span lang=\"en-AE\" style=\"font-size:14.0pt;line-height:\r\n115%\">Head – Job Card Execution</span></b></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">\r\nRole Purpose<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"en-AE\">Ensure <b>job card processes are strictly\r\nfollowed</b> and execution meets approved scope, accuracy, and timelines.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><b><span lang=\"en-AE\"><br>\r\nAbsolute Ownership<o:p></o:p></span></b></p>\r\n\r\n<ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Job Card Process<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Job Card SLA adherence<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Job Card violation detection<o:p></o:p></span></li>\r\n</ul>\r\n\r\n<p class=\"MsoNormal\"><b><span lang=\"en-AE\"><br>\r\nKey Responsibilities<o:p></o:p></span></b></p>\r\n\r\n<ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Ensure execution strictly follows approved job cards<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Monitor and enforce job card SLA adherence<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Detect, report, and correct job card violations<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Coordinate and resolve complaints related to job execution<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Ensure minimal rework and execution errors<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Issue fines timely & accurately<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Any other work assigned by immediate supervisor<o:p></o:p></span></li>\r\n</ul>\r\n\r\n<p class=\"MsoNormal\"><b><span lang=\"en-AE\"><br>\r\nPerformance KPIs<o:p></o:p></span></b></p>\r\n\r\n<ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Timely execution as per SLA <b>>98%</b><o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Accurate execution as per SLA <b>>98%</b></span></li><li class=\"MsoNormal\"><span lang=\"en-AE\"><b><span style=\"font-weight: 400;\">Rework percentage </span><span style=\"font-weight: bolder; font-size: 12pt; font-family: Aptos, \" sans-serif\";\"=\"\"><2%</span><br></b></span><br></li></ul>', '', '2026-01-31 05:00:00', '2026-01-31 17:00:00', 'Sunday', 27, 1, 1, 520416, 2, 700, 0, NULL, 'Yes'),
