(492, 'Adnan Nawab Noor Ul Wahab', '../../uploads/17676924082310.jpeg', 'Nawab', 'a2293e833c3cf9902b35eac81882bd29', 'Battery Technician', 'Not Available', 'Adnanbacha112000@gmail.com', 3000, 1500, 'RSA', 'RSA Operations', 'Battery Technician', '2026-01-05', '2027-01-08', '[\"https://cg2uploads.s3.amazonaws.com/1767693360235.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1767693360234.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1767693360234.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1767693360233.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1767693360235.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1767693360232.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1767693360236.jpeg\"]', '', '', '', '', '', '', '', 'AT9630111', 'With Them', '2027-05-29', '0000-00-00', '0001-01-01', '0001-01-01', 'Pakistan', 'OUTSIDE', '2000-05-11', '784-2000-9599355-4', '2027-01-07 20:00:00', 'Supervisor', 0, '', 'Employed', '', 1, 0, '', '', '', 0, '', '', 33, '', '2026-01-06 09:40:08', 556690093, '', 'Dubai, UAE', '<p><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">1. Make sure all drivers are reaching on time on assigned leads and make sure all drivers are available as well.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">2. Real time leads closing with photo and Invoices punch verification.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">3. Make sure all orders are punched on time and correctly with full information.</span></p>', NULL, '2026-03-07 03:00:00', '2026-03-07 15:00:00', 'Tuesday', 0, 0, 2, 52041, 2, 700, 0, NULL, 'Yes'),
(493, 'Sagar Vijay Avhad Vijay Nivrutti Avhad', '../../uploads/17682241914987.jpeg', 'Sagar', 'cf299ba19ce28e89a055d8db3e5578a0', 'Head – Inspection & Minor Services Operations ', '0504349611', 'avhadsagar65@gmail.com', 4000, 2500, 'Service Center', 'Third Party Garage Operations Department', 'Service Coordinator', '2026-01-15', '2026-09-22', '[\"https://cg2uploads.s3.amazonaws.com/1768918320527.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1768918320526.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1768918320524.pdf\",\"https://cg2uploads.s3.amazonaws.com/1768918320527.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1768918320528.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1768918320529.jpeg\",\"https://cg2uploads.s3.amazonaws.com/1768918320530.pdf\"]', '', '', '', '', '', '', '', 'I0062294', 'With Them', '2035-08-06', '0000-00-00', '0001-01-01', '0001-01-01', 'Indian', 'OUTSIDE', '1994-04-11', '784199470733108', '2026-09-21 20:00:00', 'Manager', 0, '', 'Employed', '', 1, 1, '', '', '', 1, '', '', 0, '', '2026-01-12 13:23:10', 585762034, '', 'Dubai,UAE', '<p class=\"MsoNormal\" style=\"text-indent:.5in\"><br></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\" style=\"font-size:14.0pt;line-height:\r\n115%\">Head – Inspection & Minor Services Operations</span></b><b style=\"text-align: center; font-size: 1rem;\"><span lang=\"en-AE\"> </span></b></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Role Purpose<o:p></o:p></span></b></p><p class=\"MsoNormal\"><span lang=\"en-AE\">Own <b>inspection + minor services\r\naccuracy, flow, and SLA</b> across all service centres and mobile operations.</span></p><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Absolute Ownership<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Inspection & minor services process<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Inspection & minor services SLA adherence<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Inspection & minor services accuracy</span></li></ul><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Key Responsibilities<o:p></o:p></span></b></p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Ensure <b>inspection + minor services</b> are completed within\r\n     SLA<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Maintain high inspection and minor services accuracy<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Improve inspection & minor services workflows<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Coordinate and manage complaints related to inspection and\r\n     minor services<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Issue fines accurately and timely.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Ensure team adherence to SOPs<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Any other work assigned by immediate supervisor</span></li></ul><p class=\"MsoNormal\"><b><span lang=\"en-AE\">Performance KPIs<o:p></o:p></span></b></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul style=\"margin-top:0in\" type=\"disc\">\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">On-time inspection <b>>90%</b><o:p></o:p></span></li>\r\n <li class=\"MsoNormal\"><span lang=\"en-AE\">Inspection accuracy score <b>>95%<o:p></o:p></b></span></li>\r\n</ul>', NULL, '2026-01-31 05:00:00', '2026-01-31 17:00:00', 'Sunday', 27, 1, 3, 520416, 2, 700, 0, NULL, 'Yes'),
(494, 'Wahab Safdar Hussain', '../../uploads/17684028144466.jpeg', 'Wahab', 'd8faabb2365ae5584028bb83e1253c3e', 'Battery Technician', 'Not Available', 'Wahabjutt078@gmail.com', 3000, 1500, 'RSA', 'RSA Operations', 'Battery Technician', '2026-01-14', '2027-03-12', '[\"https://cg2uploads.s3.amazonaws.com/1768403734977.pdf\",\"https://cg2uploads.s3.amazonaws.com/1768403734978.pdf\",\"https://cg2uploads.s3.amazonaws.com/1768403734979.pdf\",\"https://cg2uploads.s3.amazonaws.com/1768403734979.pdf\",\"https://cg2uploads.s3.amazonaws.com/1768403734979.pdf\",\"https://cg2uploads.s3.amazonaws.com/1768403734980.jpeg\"]', '', '', '', '', '', '', '', 'BE6133431', 'With Them', '2027-07-28', '0000-00-00', '0001-01-01', '0001-01-01', 'Pakistan', 'OUTSIDE', '2006-07-21', '784200675890436', '2027-03-11 20:00:00', 'Supervisor', 0, '', 'Employed', '', 1, 0, '', '', '', 0, '', '', 42, '', '2026-01-14 15:00:13', 582885653, '', 'Dubai, UAE', '<p><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">1. Maintain 90% order conversion</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">2. Check and verify the inventory, Tools, and Vehicle condition as well.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">3. Maintain 90% scrap return.</span><br style=\"font-family: Calibri, Arial; font-size: 14.6667px;\"><span style=\"font-family: Calibri, Arial; font-size: 14.6667px;\">4. Make sure “No any orders are canceled”.</span></p>', NULL, '2026-03-07 05:00:00', '2026-03-07 17:00:00', '', 0, 0, 2, 52041, 2, 700, 0, NULL, 'Yes');
