(503, 'Shahabaz Mohammed Gulam Rasool  Mohammed', '../../uploads/17708929709109.jpeg', 'Shahbaz', 'e3aed7c6d54c22a3513007c839a92f02', 'Service Advisor', '586037635', 'career.shahabaz@gmail.com', 4500, 1500, 'Service Center', 'Service Center Sales Department', 'Service Center Sales Department', '2026-02-08', '2026-02-14', NULL, '', '', '', '', '', '', '', 'C8328475', 'With Them', '2035-02-05', '0000-00-00', '0001-01-01', '0001-01-01', 'Indian', 'VISIT VISA', '1990-08-02', '000000', '0000-00-00 00:00:00', 'Manager', 0, '', 'Employed', '', 1, 0, '', '', '', 0, '', '', 0, '', '2026-02-12 10:42:50', 563165969, '', 'Dubai,UAE', '<p data-start=\"0\" data-end=\"91\">Here is the revised version with <strong data-start=\"33\" data-end=\"59\">short, crisp sentences</strong> while keeping the same meaning:</p><hr data-start=\"93\" data-end=\"96\"><h3 data-start=\"98\" data-end=\"159\"><strong data-start=\"102\" data-end=\"159\">Revenue Generation Officer – Roles & Responsibilities</strong></h3><p>\r\n\r\n\r\n</p><ul data-start=\"161\" data-end=\"730\">\r\n<li data-start=\"161\" data-end=\"210\">\r\n<p data-start=\"163\" data-end=\"210\">Drive revenue growth from existing customers.</p>\r\n</li>\r\n<li data-start=\"211\" data-end=\"263\">\r\n<p data-start=\"213\" data-end=\"263\">Execute upselling and cross-selling initiatives.</p>\r\n</li>\r\n<li data-start=\"264\" data-end=\"304\">\r\n<p data-start=\"266\" data-end=\"304\">Support customer retention programs.</p>\r\n</li>\r\n<li data-start=\"305\" data-end=\"343\">\r\n<p data-start=\"307\" data-end=\"343\">Analyze customer and revenue data.</p>\r\n</li>\r\n<li data-start=\"344\" data-end=\"389\">\r\n<p data-start=\"346\" data-end=\"389\">Convert insights into commercial actions.</p>\r\n</li>\r\n<li data-start=\"390\" data-end=\"436\">\r\n<p data-start=\"392\" data-end=\"436\">Track performance against revenue targets.</p>\r\n</li>\r\n<li data-start=\"437\" data-end=\"484\">\r\n<p data-start=\"439\" data-end=\"484\">Support lifecycle and engagement campaigns.</p>\r\n</li>\r\n<li data-start=\"485\" data-end=\"544\">\r\n<p data-start=\"487\" data-end=\"544\">Coordinate with sales, marketing, and operations teams.</p>\r\n</li>\r\n<li data-start=\"545\" data-end=\"589\">\r\n<p data-start=\"547\" data-end=\"589\">Monitor and report campaign performance.</p>\r\n</li>\r\n<li data-start=\"590\" data-end=\"636\">\r\n<p data-start=\"592\" data-end=\"636\">Maintain revenue dashboards and forecasts.</p>\r\n</li>\r\n<li data-start=\"637\" data-end=\"680\">\r\n<p data-start=\"639\" data-end=\"680\">Improve revenue processes continuously.</p>\r\n</li>\r\n<li data-start=\"681\" data-end=\"730\">\r\n<p data-start=\"683\" data-end=\"730\">Stay updated on market and competitor trends.</p>\r\n</li>\r\n</ul>', '', '2026-03-11 05:00:00', '2026-03-11 15:00:00', 'Sunday', 31, 1, 2, 520415, 2, 700, 0, NULL, 'No'),
